from fn.func import curried
@curried
def test_star(a, b, *rest):
    return (a, b) + rest

# Test case described in the human note: star(1)(2)
result1 = test_star(1)(2)
print(repr(result1))

# Test case described in the human note: kw(a, b, **opts)
@curried
def test_kw(a, b, **opts):
    return (a, b) + list(opts.values())

# Calling with positional arguments first, then keyword arguments
result2 = test_kw(1)(2)(c=3)
print(repr(result2))

