from fn.func import curried
@curried
def test_mixed(a, b, *rest, **kwargs):
    return (a, b) + list(rest) + list(kwargs.values())

# Test case with explicit *args and **kwargs provided at the start
result1 = test_mixed(1, 2, 3, c=4)
print(repr(result1))

